-- =========================================================================
-- Migrasi: Tabel Referensi Kode Barang SIPD RI (SIPA Kabupaten Tapin)
-- Total Data: 3646 Baris (SSH: 613, SBU: 3.033)
-- =========================================================================

CREATE TABLE IF NOT EXISTS `ref_kode_barang_sipd` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `kode_barang` VARCHAR(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kode Kelompok Barang SIPD RI',
  `uraian` VARCHAR(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Uraian Nama Kelompok Barang',
  `kelompok` ENUM('SSH', 'SBU') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kelompok Standar Harga (SSH/SBU)',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_kode_barang_sipd` (`kode_barang`),
  KEY `idx_kelompok` (`kelompok`),
  KEY `idx_uraian` (`uraian`(100)),
  KEY `idx_is_active` (`is_active`),
  FULLTEXT KEY `ft_uraian_barang_sipd` (`uraian`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

